using DarkColony.ContentImport;
using DarkColony.Assets;
using System.IO.Compression;
using System.Text.Json;
public static class RecoveryChecks {
 public static async Task Run(string storePath,string baseFolder,string output){
  output=Path.GetFullPath(output);Directory.CreateDirectory(output);var store=new ContentStore(storePath);string? before=store.ActiveRoot;var results=new List<object>();
  async Task Reject(string name,Func<Task> action){try{await action();throw new Exception("Unexpected acceptance: "+name);}catch(Exception e)when(e is IOException or InvalidDataException or UnauthorizedAccessException){results.Add(new{name,rejected=true,error=e.Message});}if(store.ActiveRoot!=before)throw new Exception("Activation changed after rejected input: "+name);}
  await Reject("invalid drive-root destination",()=>{_ =new ContentStore(Path.GetPathRoot(output)!);return Task.CompletedTask;});
  await Reject("insufficient-space response (controlled available=0)",()=>{ContentImporter.CheckFreeSpace(0);return Task.CompletedTask;});
  string badzip=Path.Combine(output,"traversal.zip");using(var z=ZipFile.Open(badzip,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("../outside.txt").Open());w.Write("must not escape");}
  await Reject("ZIP path traversal",async()=>{using var p=await ContentImporter.InspectAsync(store,new[]{badzip},CancellationToken.None);});if(File.Exists(Path.Combine(output,"outside.txt")))throw new Exception("Archive escaped");
  string incomplete=Path.Combine(output,"partial-game");Directory.CreateDirectory(incomplete);File.Copy(Path.Combine(baseFolder,"DC16.EXE"),Path.Combine(incomplete,"DC16.EXE"));using(var p=await ContentImporter.InspectAsync(store,new[]{incomplete},CancellationToken.None)){if(p.Findings[0].Compatible||p.Findings[0].Missing.Length<100)throw new Exception("Incomplete folder accepted");results.Add(new{name="Incomplete installed folder",missing=p.Findings[0].Missing.Length});}
  string unknown=Path.Combine(output,"unknown-game");Directory.CreateDirectory(unknown);var exe=File.ReadAllBytes(Path.Combine(baseFolder,"DC16.EXE"));exe[^1]^=1;File.WriteAllBytes(Path.Combine(unknown,"DC16.EXE"),exe);await Reject("unknown executable",async()=>{using var p=await ContentImporter.InspectAsync(store,new[]{unknown},CancellationToken.None);});
  using(var cancel=new CancellationTokenSource()){using var p=await ContentImporter.InspectAsync(store,new[]{baseFolder},cancel.Token);try{await ContentImporter.ImportAsync(p,false,cancel.Token,x=>{if(x.Stage==ImportStage.Copying)cancel.Cancel();});throw new Exception("Cancellation ignored");}catch(OperationCanceledException){results.Add(new{name="Cancel during validated file copying",preserved=store.ActiveRoot==before});}if(store.ActiveRoot!=before||store.IncompleteImports().Length!=0)throw new Exception("Cancel did not preserve active content/clean owned staging");}
  string mixed=Path.Combine(output,"mixed-game");Directory.CreateDirectory(mixed);foreach(var f in ContentContract.Current.BaseFiles){string source=Path.Combine(baseFolder,f.Path),target=Path.Combine(mixed,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(source,target);}File.Copy(Path.Combine(baseFolder,"DC16.EXE"),Path.Combine(mixed,"DC16.EXE"));string damaged=Path.Combine(mixed,"ANIM.DAT");File.SetAttributes(damaged,FileAttributes.Normal);var bytes=File.ReadAllBytes(damaged);bytes[^1]^=1;File.WriteAllBytes(damaged,bytes);
  await Reject("mixed/damaged gameplay data",async()=>{using var p=await ContentImporter.InspectAsync(store,new[]{mixed},CancellationToken.None);await ContentImporter.ImportAsync(p,false,CancellationToken.None);});
  var original=File.ReadAllBytes(Path.Combine(baseFolder,OriginalContentCorrections.Human09Path));var corrected=OriginalContentCorrections.Read(OriginalContentCorrections.Human09Path,original);var again=OriginalContentCorrections.Read(OriginalContentCorrections.Human09Path,corrected.Bytes);if(!again.Bytes.SequenceEqual(corrected.Bytes)||!ContentContract.Current.BaseFiles.Single(f=>f.Path==OriginalContentCorrections.Human09Path).Hashes.Contains(again.Sha256))throw new Exception("Known Human09 variants");results.Add(new{name="Human09 original/corrected",byteExactSourcePreserved=original.SequenceEqual(File.ReadAllBytes(Path.Combine(baseFolder,OriginalContentCorrections.Human09Path))),id=corrected.CorrectionId});
  File.WriteAllText(Path.Combine(output,"recovery.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("RECOVERY_PASS "+results.Count);
 }
}
